// GENERATED by tools/make_pixel_art.py from art/pixels/*.txt and art/palette.json. Edit the art, not this.
//
// Pixel sprites for the Live Activity, shared by the App and the widget extension. Each grid cell
// becomes one pixel of a CGImage; SwiftUI scales it with interpolation off, so one art pixel is always
// a whole number of points (or a clean 2/3 on 3x screens) and is never smoothed.

import CoreGraphics
import Foundation
import SwiftUI

enum SpriteState: String, CaseIterable, Codable {
    case calm = "calm"
    case coax = "coax"
    case crave = "crave"
    case happy = "happy"
    case miss = "miss"
    case shy = "shy"
    case sleepy = "sleepy"
    case upset = "upset"

    /// Unknown names from the server fall back to the default sprite rather than to nothing.
    init(name: String?) { self = SpriteState(rawValue: name ?? "") ?? .calm }

    func grid(wide: Bool) -> [String] {
        switch self {
        case .calm: return wide ? PixelGrids.calmWide : PixelGrids.calmCompact
        case .coax: return wide ? PixelGrids.coaxWide : PixelGrids.coaxCompact
        case .crave: return wide ? PixelGrids.craveWide : PixelGrids.craveCompact
        case .happy: return wide ? PixelGrids.happyWide : PixelGrids.happyCompact
        case .miss: return wide ? PixelGrids.missWide : PixelGrids.missCompact
        case .shy: return wide ? PixelGrids.shyWide : PixelGrids.shyCompact
        case .sleepy: return wide ? PixelGrids.sleepyWide : PixelGrids.sleepyCompact
        case .upset: return wide ? PixelGrids.upsetWide : PixelGrids.upsetCompact
        }
    }
}

